[hidden] { display: none !important; }
:root { color-scheme: light; --ink: #273331; --muted: #71807a; --paper: #fffdf7; --cream: #f4ead8; --green: #527a68; --mint: #e2eee5; --coral: #e58c70; --line: #e8e4d9; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; padding: 40px 18px; display: grid; place-items: start center; background-color: var(--cream); background-image: radial-gradient(#d9cdb5 1px, transparent 1px); background-size: 18px 18px; color: var(--ink); font: 16px/1.5 system-ui, sans-serif; }
button, input, textarea { font: inherit; }
.board { width: min(100%, 620px); padding: clamp(22px, 5vw, 42px); background: var(--paper); border: 2px solid var(--ink); border-radius: 8px; box-shadow: 8px 8px 0 #c8b99e; }
.header { display: flex; align-items: center; gap: 16px; margin-bottom: 28px; }
.pixel-mark { width: 54px; height: 54px; display: grid; place-items: center; flex: 0 0 auto; color: var(--paper); background: var(--green); border: 2px solid var(--ink); box-shadow: 4px 4px 0 var(--coral); font-size: 30px; }
.eyebrow, h1, h2, p { margin: 0; }
.eyebrow { color: var(--green); font-size: 12px; font-weight: 800; letter-spacing: .13em; }
h1 { margin-top: 2px; font-size: clamp(28px, 7vw, 38px); line-height: 1.1; letter-spacing: -.04em; }
.note-form { display: grid; gap: 9px; padding: 20px; background: #faf7ee; border: 1px solid var(--line); border-radius: 6px; }
.note-form label { margin-top: 2px; font-weight: 700; }
.note-form label span { color: var(--muted); font-size: 14px; font-weight: 500; }
input, textarea { width: 100%; padding: 12px 13px; color: var(--ink); background: white; border: 1px solid #c9d0c8; border-radius: 4px; outline: none; }
textarea { min-height: 84px; resize: vertical; }
input:focus, textarea:focus { border-color: var(--green); box-shadow: 0 0 0 3px #527a6833; }
.add-button { min-height: 48px; margin-top: 5px; padding: 10px 16px; color: white; background: var(--green); border: 2px solid var(--ink); border-radius: 4px; box-shadow: 3px 3px 0 var(--ink); font-weight: 750; cursor: pointer; transition: transform .12s, box-shadow .12s, background .12s; }
.add-button span { margin-right: 4px; font-size: 22px; vertical-align: -1px; }
.add-button:hover { background: #3f6654; }
.add-button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 var(--ink); }
button:focus-visible { outline: 3px solid var(--coral); outline-offset: 3px; }
.tag-section, .notes-section { margin-top: 29px; }
.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 12px; }
h2 { color: var(--muted); font-size: 12px; font-weight: 800; letter-spacing: .12em; }
.tag-list { display: flex; flex-wrap: wrap; gap: 8px; }
.tag-chip { display: inline-flex; align-items: center; gap: 8px; min-height: 38px; padding: 6px 10px; color: var(--green); background: var(--mint); border: 1px solid #b7cdbb; border-radius: 4px; font-size: 14px; font-weight: 700; cursor: pointer; transition: background .12s, transform .12s; }
.tag-chip:hover { background: #d1e4d5; transform: translateY(-1px); }
.tag-chip:active { transform: translateY(1px); }
.tag-chip[aria-pressed="true"] { color: white; background: var(--green); border-color: var(--ink); }
.tag-chip .count { min-width: 21px; padding: 0 5px; color: var(--ink); background: var(--paper); border-radius: 3px; text-align: center; font-size: 12px; }
.clear-button { padding: 5px 8px; color: var(--green); background: transparent; border: 1px solid #b7cdbb; border-radius: 4px; font-size: 14px; font-weight: 700; cursor: pointer; }
.clear-button:hover { background: var(--mint); }
.active-filter { margin-top: 10px; color: var(--muted); font-size: 14px; }
.notes-list { display: grid; gap: 10px; }
.note-card { padding: 15px 16px; background: white; border: 1px solid var(--line); border-left: 4px solid var(--coral); border-radius: 4px; }
.note-card p { white-space: pre-wrap; overflow-wrap: anywhere; }
.note-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px; }
.note-tag { padding: 2px 7px; color: var(--green); background: var(--mint); border-radius: 3px; font-size: 13px; }
.empty-state { padding: 20px; color: var(--muted); background: #faf7ee; border: 1px dashed #d4d0c5; border-radius: 4px; text-align: center; }
footer { margin-top: 28px; color: var(--muted); text-align: center; font-size: 13px; }
footer span { color: var(--coral); }
@media (max-width: 420px) { body { padding: 20px 12px; } .board { padding: 22px 18px; box-shadow: 5px 5px 0 #c8b99e; } .note-form { padding: 15px; } }

const form = document.querySelector('#note-form');
const textField = document.querySelector('#note-text');
const tagsField = document.querySelector('#note-tags');
const notesList = document.querySelector('#notes-list');
const tagList = document.querySelector('#tag-list');
const clearButton = document.querySelector('#clear-filter');
const activeFilter = document.querySelector('#active-filter');
const noteCount = document.querySelector('#note-count');

let notes = [];
let selectedTag = null;

function parseTags(value) {
  return [...new Set(value.split(',').map(tag => tag.trim().toLowerCase()).filter(Boolean))];
}

function render() {
  const counts = new Map();
  notes.forEach(note => note.tags.forEach(tag => counts.set(tag, (counts.get(tag) || 0) + 1)));

  tagList.replaceChildren();
  [...counts.entries()].sort(([a], [b]) => a.localeCompare(b)).forEach(([tag, count]) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'tag-chip';
    button.setAttribute('aria-pressed', String(selectedTag === tag));
    button.setAttribute('aria-label', `${tag}, ${count} ${count === 1 ? 'note' : 'notes'}`);
    const name = document.createElement('span');
    name.textContent = tag;
    const number = document.createElement('span');
    number.className = 'count';
    number.textContent = count;
    button.append(name, number);
    button.addEventListener('click', () => {
      selectedTag = selectedTag === tag ? null : tag;
      render();
    });
    tagList.append(button);
  });

  clearButton.hidden = !selectedTag;
  activeFilter.textContent = selectedTag ? `Showing notes tagged “${selectedTag}”.` : '';
  const visibleNotes = notes.filter(note => !selectedTag || note.tags.includes(selectedTag));
  noteCount.textContent = `${visibleNotes.length} ${visibleNotes.length === 1 ? 'note' : 'notes'}`;
  notesList.replaceChildren();

  if (!visibleNotes.length) {
    const empty = document.createElement('p');
    empty.className = 'empty-state';
    empty.textContent = selectedTag ? 'No notes match this tag.' : 'Your notebook is empty. Add a note to get started.';
    notesList.append(empty);
    return;
  }

  visibleNotes.forEach(note => {
    const card = document.createElement('article');
    card.className = 'note-card';
    const content = document.createElement('p');
    content.textContent = note.text;
    card.append(content);
    if (note.tags.length) {
      const tags = document.createElement('div');
      tags.className = 'note-tags';
      note.tags.forEach(tag => {
        const label = document.createElement('span');
        label.className = 'note-tag';
        label.textContent = tag;
        tags.append(label);
      });
      card.append(tags);
    }
    notesList.append(card);
  });
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = textField.value.trim();
  if (!text) return;
  notes.unshift({ text, tags: parseTags(tagsField.value) });
  textField.value = '';
  tagsField.value = '';
  render();
  textField.focus();
});

clearButton.addEventListener('click', () => {
  selectedTag = null;
  render();
});

render();
